const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const caboFrio = ee.Geometry.Point([-42.018, -22.878]);
  const region = caboFrio.buffer(50000); // 50km buffer around Cabo Frio
  const startDate = '2023-09-01';
  const endDate = '2023-09-30';

  // 2. Data Acquisition - MODIS Ocean SST
  const sstCol = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(startDate, endDate)
    .filterBounds(region)
    .select('sst');

  const colSize = sstCol.size().getInfo();
  console.log(`September 2023 SST Images: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composite to reduce cloud effects
  const sstComposite = sstCol.median();

  // 3. Calculate temperature gradient
  // Gradient magnitude = sqrt((dx)^2 + (dy)^2) in °C per degree
  // Convert to °C/km (approx 0.00899° per km at this latitude)
  const gradient = sstComposite.gradient();
  const gradMagnitude = gradient.select('sst_x').pow(2)
    .add(gradient.select('sst_y').pow(2))
    .sqrt()
    .multiply(111.32); // Convert to °C/km (approx conversion)

  // 4. Check for gradients > 0.5°C/km (5°C/10km)
  const strongGradient = gradMagnitude.gt(0.5);

  // Count valid pixels and strong gradient pixels
  const stats = strongGradient.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.sum(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const totalPixels = stats.get('count').getInfo();
  const strongGradPixels = stats.get('sum').getInfo();

  console.log(`Total valid SST pixels: ${totalPixels}`);
  console.log(`Pixels with gradient >5°C/10km: ${strongGradPixels}`);

  if (totalPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check if result is valid
  if (strongGradPixels === null || strongGradPixels === undefined || 
      isNaN(strongGradPixels) || strongGradPixels < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final determination
  const gradientPercentage = (strongGradPixels / totalPixels) * 100;
  console.log(`Strong gradient coverage: ${gradientPercentage.toFixed(2)}%`);

  if (strongGradPixels > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
